3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Converts a raw telephone into E.164 form: a leading '+' and country code are kept when
7	 * present, otherwise country code '+61' is assumed and a single leading '0' is dropped from
8	 * the national digits. Spaces, dashes and brackets (indeed every non-digit character) are
9	 * stripped, and the result must carry 8 to 15 digits after the '+'.
10	 *
11	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
12	 * tripping the one-public-method-per-function rule.
13	 */
14	public final class E164Telephone {
15	
16	    private E164Telephone() {
17	    }
18	
19	    /**
20	     * @return the E.164 form ('+' followed by 8 to 15 digits).
21	     * @throws InvalidTelephoneException if the input cannot form valid E.164.
22	     */
23	    public static String normalize(String raw) throws InvalidTelephoneException {
24	        if (raw == null) {
25	            throw new InvalidTelephoneException("Telephone is required");
26	        }
27	        boolean hasCountryCode = raw.trim().startsWith("+");
28	        String digits = raw.replaceAll("\\D", "");
29	        if (!hasCountryCode) {
30	            if (digits.startsWith("0")) {
31	                digits = digits.substring(1);
32	            }
33	            digits = "61" + digits;
34	        }
35	        if (digits.length() < 8 || digits.length() > 15) {
36	            throw new InvalidTelephoneException(
37	                    "Telephone must have 8 to 15 digits in E.164 form");
38	        }
39	        return "+" + digits;
40	    }
41	
42	    /**
43	     * Validates the national-number length of an E.164 telephone against its country code:
44	     * country code '+61' (Australia) requires exactly 9 national digits and '+1' (NANP)
45	     * requires exactly 10. Country codes without a pinned rule keep only the generic 8 to 15
46	     * digit bound enforced by {@link #normalize}.
47	     *
48	     * @param e164 an E.164 telephone as produced by {@link #normalize} ('+' then 8 to 15 digits).
49	     * @throws InvalidTelephoneException if the national-number length is wrong for the country.
50	     */
51	    public static void validateNationalNumberLength(String e164) throws InvalidTelephoneException {
52	        String digits = e164 == null ? "" : e164.replaceAll("\\D", "");
53	        CountryCode country = CountryCode.of(digits);
54	        if (country != null) {
55	            requireNationalLength(digits.length() - country.digits.length(),
56	                    country.nationalNumberLength, country.dialCode());
57	        }
58	    }
59	
60	    private static void requireNationalLength(int actual, int expected, String countryCode)
61	            throws InvalidTelephoneException {
62	        if (actual != expected) {
63	            throw new InvalidTelephoneException("Telephone with country code " + countryCode
64	                    + " must have " + expected + " national digits");
65	        }
66	    }
67	
68	    /**
69	     * Formats a stored E.164 telephone for humans: the '+' and country dial code, a space, then
70	     * the national digits grouped in threes and separated by spaces
71	     * (e.g. {@code "+61412345678"} -> {@code "+61 412 345 678"}). The country code is recognised
72	     * via the same pinned dial codes used for validation; when none is recognised (or the input
73	     * is not E.164) the value is returned unchanged. Returns {@code null} when the input is null.
74	     *
75	     * @param e164 an E.164 telephone as produced by {@link #normalize} ('+' then 8 to 15 digits).
76	     * @return the human-facing display form, or the input unchanged when it is not recognised E.164.
77	     */
78	    public static String display(String e164) {
79	        if (e164 == null) {
80	            return null;
81	        }
82	        String digits = e164.replaceAll("\\D", "");
83	        CountryCode country = CountryCode.of(digits);
84	        if (country == null || digits.length() <= country.digits.length()) {
85	            return e164;
86	        }
87	        String national = digits.substring(country.digits.length());
88	        StringBuilder sb = new StringBuilder("+").append(country.digits);
89	        for (int i = 0; i < national.length(); i += 3) {
90	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
91	        }
92	        return sb.toString();
93	    }
94	
95	    /** E.164 form of a telephone, or {@code null} when it is absent or cannot be formed. */
96	    public static String normalizeOrNull(String raw) {
97	        if (raw == null) {
98	            return null;
99	        }
100	        try {
101	            return normalize(raw);
102	        }
103	        catch (InvalidTelephoneException ex) {
104	            return null;
105	        }
106	    }
107	
108	    /**
109	     * The known E.164 country codes and the national-number length pinned for each: '+61'
110	     * (Australia) requires 9 national digits, '+1' (NANP) requires 10. A country code is
111	     * recognised when its bare dial digits lead the E.164 number's digits; splitting the dial
112	     * code off leaves the national number. Country codes with no entry here keep only the
113	     * generic 8-to-15 digit bound from {@link #normalize}.
114	     */
115	    private enum CountryCode {
116	
117	        /** Australia: '+61', 9 national digits. */
118	        AUSTRALIA("61", 9),
119	
120	        /** North American Numbering Plan: '+1', 10 national digits. */
121	        NANP("1", 10);
122	
123	        /** Bare dial-code digits, matched as a prefix of an E.164 number's digits. */
124	        private final String digits;
125	
126	        /** Exact national-number length required for this country code. */
127	        private final int nationalNumberLength;
128	
129	        CountryCode(String digits, int nationalNumberLength) {
130	            this.digits = digits;
131	            this.nationalNumberLength = nationalNumberLength;
132	        }
133	
134	        /**
135	         * The recognised country code whose dial digits lead {@code e164Digits}, or
136	         * {@code null} when none is recognised. Codes are tried in declaration order, so a
137	         * longer dial code takes precedence over a shorter one that shares its lead.
138	         */
139	        static CountryCode of(String e164Digits) {
140	            for (CountryCode country : values()) {
141	                if (e164Digits.startsWith(country.digits)) {
142	                    return country;
143	                }
144	            }
145	            return null;
146	        }
147	
